//! Doors and gates in data form (`data/doors.json`, generated by the `door_table` probe): which
//! closed object turns into which open one, and how the leaves swing. `sim::objects` opens and
//! closes them.

use serde::{Deserialize, Serialize};

/// One leaf of a door: the object while it is shut, and the one while it stands open.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DoorLeafDef {
    pub closed: u32,
    pub open: u32,
}

/// How a leaf moves when it opens, in the frame of a door on the west edge of its tile (the wall
/// running north): the tile it moves to and the quarter turns clockwise it makes. A leaf placed
/// turned `o` moves the same way turned `o` quarter turns.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LeafMove {
    pub offset: (i32, i32),
    pub turn: i32,
}

impl LeafMove {
    /// How a door on a diagonal wall (shape 9) swings open, in the frame of one turned 0 (the
    /// wall running south-west to north-east): onto the tile north of it, a quarter turn
    /// clockwise. Taken from the diagonal doors the map places open (East Ardougne's, for one),
    /// each standing so beside a gap in its diagonal wall. Diagonal doors are single leaves.
    pub const DIAGONAL: LeafMove = LeafMove { offset: (0, 1), turn: 1 };
}

/// How a door's leaves swing open. Leaves are taken in order along the wall: in the west-edge
/// frame, the first is the southern one. Each leaf of a pair opens and closes on its own.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DoorSwing {
    /// One leaf, hinged at its northern end: it swings out across the edge, a quarter turn
    /// clockwise.
    Single,
    /// Two leaves hinged at their outer ends, swinging out away from each other.
    Double,
    /// A two-leaf gate, swinging like a double door.
    Gate,
}

impl DoorSwing {
    pub fn leaf_count(self) -> usize {
        self.moves().len()
    }

    /// How each leaf moves as it opens, in order along the wall.
    pub fn moves(self) -> &'static [LeafMove] {
        const OUT_CLOCKWISE: LeafMove = LeafMove { offset: (-1, 0), turn: 1 };
        const OUT_ANTICLOCKWISE: LeafMove = LeafMove { offset: (-1, 0), turn: -1 };
        match self {
            DoorSwing::Single => &[OUT_CLOCKWISE],
            DoorSwing::Double | DoorSwing::Gate => &[OUT_ANTICLOCKWISE, OUT_CLOCKWISE],
        }
    }
}

fn yes() -> bool {
    true
}

/// A kind of door or gate.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DoorDef {
    pub id: String,
    pub swing: DoorSwing,
    /// One leaf for a single door, two for a pair (in either order: which is which along the
    /// wall is worked out from where they stand).
    pub leaves: Vec<DoorLeafDef>,
    /// False for doors that stay open (bank doors).
    #[serde(default = "yes")]
    pub can_close: bool,
    /// The sound of a leaf opening, if not the usual one for its swing (see [`DoorDef::sound`]).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub open_sound: Option<u32>,
    /// The sound of a leaf closing, likewise.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub close_sound: Option<u32>,
}

impl DoorDef {
    /// Whether `object` is one of this door's leaves, and whether that is its open form.
    pub fn state_of(&self, object: u32) -> Option<bool> {
        self.leaf(object).map(|leaf| leaf.open == object)
    }

    /// The sound a leaf makes opening (or `closing`): the door's own, else a gate's or a door's.
    pub fn sound(&self, closing: bool) -> u32 {
        use crate::sim::sounds;
        let (own, door, gate) = if closing {
            (self.close_sound, sounds::DOOR_CLOSE, sounds::GATE_CLOSE)
        } else {
            (self.open_sound, sounds::DOOR_OPEN, sounds::GATE_OPEN)
        };
        own.unwrap_or(if self.swing == DoorSwing::Gate { gate } else { door })
    }

    /// The leaf that `object` is a form of.
    pub fn leaf(&self, object: u32) -> Option<DoorLeafDef> {
        self.leaves.iter().copied().find(|leaf| leaf.closed == object || leaf.open == object)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_door_knows_its_leaves_and_their_state() {
        let door = DoorDef {
            id: "d".into(),
            swing: DoorSwing::Double,
            leaves: vec![DoorLeafDef { closed: 1, open: 2 }, DoorLeafDef { closed: 3, open: 4 }],
            can_close: true,
            open_sound: None,
            close_sound: None,
        };
        assert_eq!(door.state_of(1), Some(false));
        assert_eq!(door.state_of(4), Some(true));
        assert_eq!(door.state_of(5), None);
        assert_eq!(door.leaf(4), Some(DoorLeafDef { closed: 3, open: 4 }));
    }

    #[test]
    fn doors_and_gates_sound_their_own_way_unless_told() {
        use crate::sim::sounds;
        let leaves = vec![DoorLeafDef { closed: 1, open: 2 }];
        let door = DoorDef { id: "d".into(), swing: DoorSwing::Single, leaves, can_close: true, open_sound: None, close_sound: None };
        assert_eq!((door.sound(false), door.sound(true)), (sounds::DOOR_OPEN, sounds::DOOR_CLOSE));
        let gate = DoorDef { swing: DoorSwing::Gate, ..door.clone() };
        assert_eq!((gate.sound(false), gate.sound(true)), (sounds::GATE_OPEN, sounds::GATE_CLOSE));
        let creaky = DoorDef { open_sound: Some(56), ..door };
        assert_eq!((creaky.sound(false), creaky.sound(true)), (56, sounds::DOOR_CLOSE));
    }
}
